export const LINES = [["From the start?", 5.54, 6.39], ["All right.", 7.0, 7.45], ["A year ago I had forty windows open and couldn't find anything.", 7.948, 11.188], ["Then I installed a small program called Spaceman.", 11.468, 14.388], ["It tiles your windows, so they sit side by side and nothing is hidden behind anything else.", 14.748, 19.948], ["It also gives you numbered workspaces.", 20.268, 22.548], ["My work went on one and my messages on two.", 22.828, 25.454], ["I had a camera on my front door, and that's only another window, so I put it on three.", 25.814, 29.916], ["I found it pleasing.", 30.436, 31.541], ["So I bought one or two more, and I gave each of my neighbours a workspace of their own.", 36.376, 40.908], ["Mark is four.", 41.268, 42.308], ["Joan is five.", 42.628, 43.828], ["Alan is six.", 44.148, 45.175], ["I like to know my neighbours.", 45.655, 46.98], ["Alan's hedge was a little over the limit, so I took a few photographs, for the record.", 49.915, 54.3], ["And Joan and I disagreed about which day the bins go out.", 60.135, 63.295], ["I'd kept seven empty, because it's useful to have somewhere to put things.", 67.655, 71.539], ["I moved Joan there in March, and I've looked after her cat ever since.", 71.899, 75.703], ["I moved Mark in June.", 76.063, 77.543], ["Where is Alan now?", 78.678, 80.043], ["He's on seven, with the other two.", 80.888, 83.208], ["And what is on seven?", 84.843, 86.362], ["Only the one window.", 87.227, 88.507], ["It's my favourite, I think.", 88.827, 90.229], ["Everything in it stays exactly where I put it.", 90.589, 92.949], ["You should try it, Detective.", 94.909, 96.369], ["You look like a man with a great many windows open.", 96.838, 99.105]]
